INSERT INTO `bowtie_preguntas` (`id`, `dimension_id`, `texto`, `evidencia`, `orden`, `creado_en`, `actualizado_en`, `activo`) VALUES
(1, 1, '¿Está documentado el proceso para la planificación, identificación, ejecución y control para realizar el corte efectivo de energía?', '1. Verificar que el proceso para el corte efectivo de energía esté documentado, actualizado, difundido y evaluado. Reglamento de bloqueo divisional, SODI (sobre 1000 Volt) y procedimientos o instructivos especificos.', 0, '2025-11-24 11:12:50', '2025-11-24 11:13:58', 0),
(2, 2, '¿Está documentado el proceso para la planificación, identificación, ejecución y control para realizar el corte efectivo de energía?', '1. Verificar que el proceso para el corte efectivo de energía esté documentado, actualizado, difundido y evaluado. Reglamento de bloqueo divisional, SODI (sobre 1000 Volt) y procedimientos o instructivos especificos.', 0, '2025-11-24 11:13:59', '2025-11-24 11:14:33', 0),
(3, 2, '¿Está definido el personal habilitado para efectuar corte de energía y cuáles son las competencias técnicas?', '1. Verificar: listado de profesionales y/o técnicos autorizados a realizar corte efectivo de energía.', 1, '2025-11-24 11:13:59', '2025-11-24 11:14:33', 0),
(4, 2, '¿Se encuentran identificados y señalizados en las instalaciones y equipos los puntos validados para realizar un corte efectivo de energía?', '1. Planos unilineales actualizados de instalaciones y equipos eléctricos que indiquen el nivel de tensión presente y tengan identificados los puntos para efectuar un corte de energía efectivo.', 2, '2025-11-24 11:13:59', '2025-11-24 11:14:33', 0),
(5, 3, '¿Está documentado el proceso para la planificación, identificación, ejecución y control para realizar el corte efectivo de energía?', '1. Verificar que el proceso para el corte efectivo de energía esté documentado, actualizado, difundido y evaluado. Reglamento de bloqueo divisional, SODI (sobre 1000 Volt) y procedimientos o instructivos especificos.', 0, '2025-11-24 11:14:33', '2025-11-24 11:15:03', 0),
(6, 3, '¿Está definido el personal habilitado para efectuar corte de energía y cuáles son las competencias técnicas?', '1. Verificar: listado de profesionales y/o técnicos autorizados a realizar corte efectivo de energía.', 1, '2025-11-24 11:14:33', '2025-11-24 11:15:03', 0),
(7, 3, '¿Se encuentran identificados y señalizados en las instalaciones y equipos los puntos validados para realizar un corte efectivo de energía?', '1. Planos unilineales actualizados de instalaciones y equipos eléctricos que indiquen el nivel de tensión presente y tengan identificados los puntos para efectuar un corte de energía efectivo.', 2, '2025-11-24 11:14:33', '2025-11-24 11:15:03', 0),
(8, 3, '¿Se cumple con el proceso para otorgar permiso para el corte efectivo de energía y los factores de erosión del control?', '1. Solicitar el permiso de trabajo para asegurar que se haya completado en forma debida, cuente con las firmas correspondientes y se encuentre vigente: SODI o anexos de acuerdo al reglamento de bloqueo divisional.', 3, '2025-11-24 11:14:33', '2025-11-24 11:15:03', 0),
(9, 4, '¿Está documentado el proceso para la planificación, identificación, ejecución y control para realizar el corte efectivo de energía?', '1. Verificar que el proceso para el corte efectivo de energía esté documentado, actualizado, difundido y evaluado. Reglamento de bloqueo divisional, SODI (sobre 1000 Volt) y procedimientos o instructivos especificos.', 0, '2025-11-24 11:15:04', '2025-11-24 12:34:21', 0),
(10, 4, '¿Está definido el personal habilitado para efectuar corte de energía y cuáles son las competencias técnicas?', '1. Verificar: listado de profesionales y/o técnicos autorizados a realizar corte efectivo de energía.', 1, '2025-11-24 11:15:04', '2025-11-24 12:34:21', 0),
(11, 4, '¿Se encuentran identificados y señalizados en las instalaciones y equipos los puntos validados para realizar un corte efectivo de energía?', '1. Planos unilineales actualizados de instalaciones y equipos eléctricos que indiquen el nivel de tensión presente y tengan identificados los puntos para efectuar un corte de energía efectivo.', 2, '2025-11-24 11:15:04', '2025-11-24 12:34:21', 0),
(12, 5, '¿Está documentado el proceso para la planificación, identificación, ejecución y control para realizar el corte efectivo de energía?', '1. Verificar que el proceso para el corte efectivo de energía esté documentado, actualizado, difundido y evaluado. Reglamento de bloqueo divisional, SODI (sobre 1000 Volt) y procedimientos o instructivos especificos.', 0, '2025-11-24 12:34:21', '2025-11-24 12:39:58', 0),
(13, 5, '¿Está definido el personal habilitado para efectuar corte de energía y cuáles son las competencias técnicas?', '1. Verificar: listado de profesionales y/o técnicos autorizados a realizar corte efectivo de energía.', 1, '2025-11-24 12:34:21', '2025-11-24 12:39:58', 0),
(14, 5, '¿Se encuentran identificados y señalizados en las instalaciones y equipos los puntos validados para realizar un corte efectivo de energía?', '1. Planos unilineales actualizados de instalaciones y equipos eléctricos que indiquen el nivel de tensión presente y tengan identificados los puntos para efectuar un corte de energía efectivo.', 2, '2025-11-24 12:34:21', '2025-11-24 12:39:58', 0),
(15, 6, '¿Se cumple con el proceso para otorgar permiso para el corte efectivo de energía y los factores de erosión del control?', '1. Solicitar el permiso de trabajo para asegurar que se haya completado en forma debida, cuente con las firmas correspondientes y se encuentre vigente: SODI o anexos de acuerdo al reglamento de bloqueo divisional.', 0, '2025-11-24 12:34:21', '2025-11-24 12:39:58', 0),
(16, 6, '¿El personal que realiza el corte de energía es el que se encuentra autorizado?', '1. Verificar en terreno que el personal eléctrico porta su Licencia eléctrica interna y que cuya autorización esté acorde a los trabajos que realiza.', 1, '2025-11-24 12:34:21', '2025-11-24 12:39:58', 0),
(17, 6, '¿La identificación y señalización de los puntos para el corte de energía se efectúa de acuerdo a lo definido?', '1. Se encuentre identificado el nivel de tensión presente.\n2. Estén identificados los puntos donde se debe realizar el corte de energía.\n3. Registro de planos unilineales vigentes.\n4. Existencia de planos unilineales actualizados.\n5. Revisar que la nomenclatura utilizada en los planos para la identificación de puntos para el corte de energía es la que se ha establecido.\n6. Revisar que la señalización definida es la que se está utilizando para la identificación de los puntos para el corte de energía.', 2, '2025-11-24 12:34:21', '2025-11-24 12:39:58', 0),
(18, 6, '¿Los instrumentos utilizados para medir tensión son los que están validados por el centro de trabajo?', '1. Verificar que los equipos utilizados se encuentran en el listado de equipos e instrumentos divionales, identificando aquellos que requieran calibración y/o cerificación', 3, '2025-11-24 12:34:21', '2025-11-24 12:39:58', 0),
(19, 7, '¿Está documentado el proceso para la planificación, identificación, ejecución y control para realizar el corte efectivo de energía?', '1. Verificar que el proceso para el corte efectivo de energía esté documentado, actualizado, difundido y evaluado. Reglamento de bloqueo divisional, SODI (sobre 1000 Volt) y procedimientos o instructivos especificos.', 0, '2025-11-24 12:39:58', '2025-11-24 12:40:35', 0),
(20, 7, '¿Está definido el personal habilitado para efectuar corte de energía y cuáles son las competencias técnicas?', '1. Verificar: listado de profesionales y/o técnicos autorizados a realizar corte efectivo de energía.', 1, '2025-11-24 12:39:58', '2025-11-24 12:40:35', 0),
(21, 7, '¿Se encuentran identificados y señalizados en las instalaciones y equipos los puntos validados para realizar un corte efectivo de energía?', '1. Planos unilineales actualizados de instalaciones y equipos eléctricos que indiquen el nivel de tensión presente y tengan identificados los puntos para efectuar un corte de energía efectivo.', 2, '2025-11-24 12:39:58', '2025-11-24 12:40:35', 0),
(22, 8, '¿Se cumple con el proceso para otorgar permiso para el corte efectivo de energía y los factores de erosión del control?', '1. Solicitar el permiso de trabajo para asegurar que se haya completado en forma debida, cuente con las firmas correspondientes y se encuentre vigente: SODI o anexos de acuerdo al reglamento de bloqueo divisional.', 0, '2025-11-24 12:39:58', '2025-11-24 12:40:35', 0),
(23, 8, '¿El personal que realiza el corte de energía es el que se encuentra autorizado?', '1. Verificar en terreno que el personal eléctrico porta su Licencia eléctrica interna y que cuya autorización esté acorde a los trabajos que realiza.', 1, '2025-11-24 12:39:58', '2025-11-24 12:40:35', 0),
(24, 8, '¿La identificación y señalización de los puntos para el corte de energía se efectúa de acuerdo a lo definido?', '1. Se encuentre identificado el nivel de tensión presente.\n2. Estén identificados los puntos donde se debe realizar el corte de energía.\n3. Registro de planos unilineales vigentes.\n4. Existencia de planos unilineales actualizados.\n5. Revisar que la nomenclatura utilizada en los planos para la identificación de puntos para el corte de energía es la que se ha establecido.\n6. Revisar que la señalización definida es la que se está utilizando para la identificación de los puntos para el corte de energía.', 2, '2025-11-24 12:39:59', '2025-11-24 12:40:35', 0),
(25, 8, '¿Los instrumentos utilizados para medir tensión son los que están validados por el centro de trabajo?', '1. Verificar que los equipos utilizados se encuentran en el listado de equipos e instrumentos divionales, identificando aquellos que requieran calibración y/o cerificación', 3, '2025-11-24 12:39:59', '2025-11-24 12:40:35', 0),
(26, 9, '¿Se han establecido auditorías/inspecciones al proceso de aislación y bloqueo?', '1. Revisar que se cuente con un programa de auditoría que indique nombre del responsable de ejecutarlas, fecha de ejecución y la frecuencia. \n2. Revisar que se cuente con informes de brechas detectadas y las acciones realizadas para el levantamiento de estas.\n3. Revisar que en caso de brechas no cerradas cuya fecha de cierre se haya cumplido, solicitar un plan de acción y responsables de su cumplimiento.', 0, '2025-11-24 12:39:59', '2025-11-24 12:40:35', 0),
(27, 10, '¿Está documentado el proceso para la planificación, identificación, ejecución y control para realizar el corte efectivo de energía?', '1. Verificar que el proceso para el corte efectivo de energía esté documentado, actualizado, difundido y evaluado. Reglamento de bloqueo divisional, SODI (sobre 1000 Volt) y procedimientos o instructivos especificos.', 0, '2025-11-24 12:40:35', '2025-11-24 12:41:55', 0),
(28, 10, '¿Está definido el personal habilitado para efectuar corte de energía y cuáles son las competencias técnicas?', '1. Verificar: listado de profesionales y/o técnicos autorizados a realizar corte efectivo de energía.', 1, '2025-11-24 12:40:35', '2025-11-24 12:41:55', 0),
(29, 10, '¿Se encuentran identificados y señalizados en las instalaciones y equipos los puntos validados para realizar un corte efectivo de energía?', '1. Planos unilineales actualizados de instalaciones y equipos eléctricos que indiquen el nivel de tensión presente y tengan identificados los puntos para efectuar un corte de energía efectivo.', 2, '2025-11-24 12:40:35', '2025-11-24 12:41:55', 0),
(30, 11, '¿Se cumple con el proceso para otorgar permiso para el corte efectivo de energía y los factores de erosión del control?', '1. Solicitar el permiso de trabajo para asegurar que se haya completado en forma debida, cuente con las firmas correspondientes y se encuentre vigente: SODI o anexos de acuerdo al reglamento de bloqueo divisional.', 0, '2025-11-24 12:40:35', '2025-11-24 12:41:55', 0),
(31, 11, '¿El personal que realiza el corte de energía es el que se encuentra autorizado?', '1. Verificar en terreno que el personal eléctrico porta su Licencia eléctrica interna y que cuya autorización esté acorde a los trabajos que realiza.', 1, '2025-11-24 12:40:35', '2025-11-24 12:41:55', 0),
(32, 11, '¿La identificación y señalización de los puntos para el corte de energía se efectúa de acuerdo a lo definido?', '1. Se encuentre identificado el nivel de tensión presente.\n2. Estén identificados los puntos donde se debe realizar el corte de energía.\n3. Registro de planos unilineales vigentes.\n4. Existencia de planos unilineales actualizados.\n5. Revisar que la nomenclatura utilizada en los planos para la identificación de puntos para el corte de energía es la que se ha establecido.\n6. Revisar que la señalización definida es la que se está utilizando para la identificación de los puntos para el corte de energía.', 2, '2025-11-24 12:40:35', '2025-11-24 12:41:55', 0),
