INSERT INTO `bowtie_preguntas` (`id`, `dimension_id`, `texto`, `evidencia`, `orden`, `creado_en`, `actualizado_en`, `activo`) VALUES
(1632, 681, '¿Están definidos el estándar, procedimientos ANUAL o reglamentos específicos que respalden el CC Identificación, aislación, bloqueo, verificación de energía cero y liberación de energía??', '3. Solicitud de permiso para la aislación y bloqueo. (Identificación de responsables)', 2, '2025-12-03 18:03:46', '2025-12-03 18:05:50', 0),
(1633, 682, '¿Están definidos el estándar, procedimientos ANUAL o reglamentos específicos que respalden el CC Identificación, aislación, bloqueo, verificación de energía cero y liberación de energía??', '1. Verificar que se utilice la última versión vigente y aprobado del documento local que respalde el control crítico de Identificación, aislación, bloqueo, verificación de energía cero y liberación de energía.', 0, '2025-12-03 18:05:50', '2025-12-03 18:08:59', 0),
