(1037, 131, 'ED-CCP1-IEE', '', '', '2. Estén identificados los puntos donde se debe realizar el corte de energía.', '', NULL, '', '', '', NULL, '', NULL, '', '', 6, 0, '2025-12-01 13:34:30', '2025-12-01 13:34:39', 389, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
(1038, 131, 'ED-CCP1-IEE', '', '', '3. Registro de planos unilineales vigentes.', '', NULL, '', '', '', NULL, '', NULL, '', '', 7, 0, '2025-12-01 13:34:30', '2025-12-01 13:34:39', 389, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
(1039, 131, 'ED-CCP1-IEE', '', '', '4. Existencia de planos unilineales actualizados.', '', NULL, '', '', '', NULL, '', NULL, '', '', 8, 0, '2025-12-01 13:34:30', '2025-12-01 13:34:39', 389, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
