(1051, 131, 'ED-CCP3-IEE', '', '', '3. Revisar que los instrumentos de medición se encuentren en buen estado.', '', NULL, '', '', '', NULL, '', NULL, '', '', 20, 0, '2025-12-01 13:34:30', '2025-12-01 13:34:39', 391, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
(1052, 131, 'ED-CCP3-IEE', '', '', '4. Revisar que las puestas a tierra se encuentren en buenas condiciones y sean las adecuadas.', '', NULL, '', '', '', NULL, '', NULL, '', '', 21, 0, '2025-12-01 13:34:30', '2025-12-01 13:34:39', 391, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
(1053, 131, 'ED-CCP3-IEE', '', '¿Están documentados los requerimientos para puesta a tierra?', '1. Verificar que exista un documento, actualizado y validado por el centro de trabajo acorde a la tensión y corriente de falla.', '', NULL, '', '', '', NULL, '', NULL, '', '', 22, 0, '2025-12-01 13:34:30', '2025-12-01 13:34:39', 391, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
