(1087, 131, 'ED-CCP5-IEE', '', '', 'Registro proceso bloqueo', '', NULL, '', '', '', NULL, '', NULL, '', '', 56, 0, '2025-12-01 13:34:30', '2025-12-01 13:34:39', 393, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
(1088, 131, 'ED-CCP5-IEE', '', '', '2. Selección y uso adecuado del instrumento de verificación de energía cero.', '', NULL, '', '', '', NULL, '', NULL, '', '', 57, 0, '2025-12-01 13:34:30', '2025-12-01 13:34:39', 393, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
