(3467, 153, 'ED-CCP4-IEE', 'DISEÑO', '¿Están definidos los requerimientos de diseño para tableros eléctricos?', '1. Verificar que existe un check list para revisión de tableros que contenga como mínimo:', '', NULL, '', '', '', NULL, 'Crítico', NULL, '', '', 30, 0, '2025-12-01 13:33:55', '2025-12-01 13:34:30', 392, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
(3468, 153, 'ED-CCP4-IEE', '', '', 'Cumplimiento del diseño, protecciones eléctricas, que se encuentre cerrado, señalética de riesgo eléctrico y responsable del equipo.', '', NULL, '', '', '', NULL, '', NULL, '', '', 31, 0, '2025-12-01 13:33:55', '2025-12-01 13:34:30', 392, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
