INSERT INTO `carpeta_linea_base` (`id`, `carpeta_id`, `codigo`, `dimension`, `pregunta`, `evidencia`, `verificador_responsable`, `fecha_verificacion`, `implementado_estandar`, `accion_ejecutar`, `responsable_cierre`, `fecha_cierre`, `criticidad`, `porcentaje_avance`, `nombre_dueno_control`, `ultimo_usuario_edito`, `orden`, `activo`, `creado_en`, `actualizado_en`, `control_preventivo_id`, `estado_validacion`, `comentario_validacion`, `usuario_validacion`, `fecha_validacion`, `ponderacion`, `comentario_trabajador`, `archivos_respaldo`, `conversacion_seguimiento`) VALUES
(3918, 153, 'ED-CCP6-IEE', '', '¿Está definido cuáles son las competencias técnicas del personal que está autorizado a ingresar en recintos que contiene sistemas eléctricos energizados?', '1. Revisar listado personal autorizado', '', NULL, '', '', '', NULL, '', NULL, '', '', 65, 0, '2025-12-01 15:20:29', '2025-12-01 16:35:36', 394, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
(3919, 153, 'ED-CCP6-IEE', '', '', '2. Revisar que las salas eléctricas cuenten con mecanismos de acceso restringido.', '', NULL, '', '', '', NULL, '', NULL, '', '', 67, 0, '2025-12-01 15:20:29', '2025-12-01 16:35:36', 394, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
(3920, 153, 'ED-CCP6-IEE', '', '¿Existe un listado de salas eléctricas de la división?', '1. Registro con salas eléctricas con el área responsable.', '', NULL, '', '', '', NULL, '', NULL, '', '', 68, 0, '2025-12-01 15:20:29', '2025-12-01 16:35:36', 394, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
(3921, 153, 'ED-CCP7-IEE', '', '', '2. Verificar que esté designada la persona responsable de elaborar el plan de mantenimiento.', '', NULL, '', '', '', NULL, '', NULL, '', '', 70, 0, '2025-12-01 15:20:29', '2025-12-01 16:35:36', 395, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
(3922, 153, 'ED-CCP7-IEE', '', '', '3. Verificar que el plan de mantenimiento considere información el mantenimiento predictivo y preventivo teniendo en cuenta información técnica y manuales de operación de equipos e instalaciones eléctricas.', '', NULL, '', '', '', NULL, '', NULL, '', '', 71, 0, '2025-12-01 15:20:29', '2025-12-01 16:35:36', 395, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
(3923, 153, 'ED-CCP7-IEE', '', '', '4. Verificar la disposición de instructivos en caso de requerir mantenimiento a equipos e instalaciones nuevas y/o instalaciones eléctricas críticas para la continuidad operacional.', '', NULL, '', '', '', NULL, '', NULL, '', '', 72, 0, '2025-12-01 15:20:29', '2025-12-01 16:35:36', 395, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
(3924, 153, 'ED-CCP7-IEE', '', '¿Se han definido los criterios para reparaciones o reemplazo de partes o piezas de equipos e instalaciones eléctricas?', '1. El documento debe indicar disponer de tecnología que permita realizar un programa de mantenimiento predictivo detectando posibles fallas, daños o desgaste antes de que el equipo falle.', '', NULL, '', '', '', NULL, '', NULL, '', '', 73, 0, '2025-12-01 15:20:29', '2025-12-01 16:35:36', 395, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
(3925, 153, 'ED-CCP7-IEE', '', '', '2. El documento debe indicar disponer de un programa de mantenimiento preventivo que permita revisiones periódicas en forma permanente.', '', NULL, '', '', '', NULL, '', NULL, '', '', 74, 0, '2025-12-01 15:20:29', '2025-12-01 16:35:36', 395, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
(3926, 153, 'ED-CCP7-IEE', '', '', '3. El documento debe indicar disponer de personal competente para autorizar modificaciones, reparaciones y/o cambios de componentes de los sistemas eléctricos.', '', NULL, '', '', '', NULL, '', NULL, '', '', 75, 0, '2025-12-01 15:20:29', '2025-12-01 16:35:36', 395, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
(3927, 153, 'ED-CCP7-IEE', '', '¿Están definidos los equipos e instalaciones eléctricas críticas que requieren prioridad en el plan de mantenimiento?', '1. Evidenciar mediante un estudio técnico que indique los equipos e instalaciones que requieren mantenimiento y que indique su periodicidad.', '', NULL, '', '', '', NULL, '', NULL, '', '', 76, 0, '2025-12-01 15:20:29', '2025-12-01 16:35:36', 395, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
(3928, 153, 'ED-CCP7-IEE', '', '', '2. Verificar que se mantenga actualizado un listado de equipos críticos.', '', NULL, '', '', '', NULL, '', NULL, '', '', 77, 0, '2025-12-01 15:20:29', '2025-12-01 16:35:36', 395, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
(3929, 153, 'ED-CCP7-IEE', '', '', '2. Verificar en terreno el cumplimiento del plan de mantenimiento.', '', NULL, '', '', '', NULL, '', NULL, '', '', 79, 0, '2025-12-01 15:20:29', '2025-12-01 16:35:36', 395, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
(3930, 153, 'ED-CCP7-IEE', '', '¿El personal eléctrico ha sido capacitado y con evaluación aprobada y vigente  en los procesos de mantención para equipos e instalaciones eléctricas y conoce los factores de erosión?', '1. Revisar que se han abordado todos los ítems de la capacitación para el logro de las competencias del personal electricista.', '', NULL, '', '', '', NULL, '', NULL, '', '', 80, 0, '2025-12-01 15:20:29', '2025-12-01 16:35:36', 395, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
(3931, 153, 'ED-CCP8-IEE', '', '¿Se ha definido la confección de un estudio de necesidad de EPP para ejecutar maniobras con equipos e instalaciones energizadas?', '1. Verificar que se haya definido la confección de un estudio de necesidad de EPP, que indique las especificaciones de EPP esté de acuerdo con el estudio de energía incidental.', '', NULL, '', '', '', NULL, '', NULL, '', '', 83, 0, '2025-12-01 15:20:29', '2025-12-01 16:35:36', 396, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
(3932, 153, 'ED-CCP8-IEE', '', '', '2. Verificar que se haya definido la confección de un estudio de necesidad de EPP, que indique las características y tipo de EPP de acuerdo al nivel de tensión que se requiere trabajar.', '', NULL, '', '', '', NULL, '', NULL, '', '', 84, 0, '2025-12-01 15:20:29', '2025-12-01 16:35:36', 396, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
(3933, 153, 'ED-CCP8-IEE', '', '¿Se ha diseñado el proceso de pruebas a equipos e instalaciones eléctricas?', '1.Se debe verificar procedimientos e instructivos especificos para la realizacion de pruebas y mediciones de equipos eléctricos', '', NULL, '', '', '', NULL, '', NULL, '', '', 85, 0, '2025-12-01 15:20:29', '2025-12-01 16:35:36', 396, NULL, '', '', NULL, 0.00, '', '[]', '[]'),
